class Solution {     public int concatenatedBinary(int n) {         final int MOD = 1_000_000_007;          StringBuilder sb = new StringBuilder();         for (int i = 1; i <= n; i++) {             sb.append(Integer.toBinaryString(i));         }          String res = sb.toString();         long ans = 0;            for (int j = 0; j < res.length(); j++) {             int bit = res.charAt(j) - '0';              ans = (ans * 2 + bit) % MOD;         }          return (int) ans;     } }